class PhoneDirectory {
    queue<int> freeNumbers;
    vector<bool> used;
public:
    PhoneDirectory(int maxNumbers) : used(maxNumbers, false) {
        for (int i = 0; i < maxNumbers; ++i) freeNumbers.push(i);
    }
    int get() {
        if (freeNumbers.empty()) return -1;
        int number = freeNumbers.front();
        freeNumbers.pop();
        used[number] = true;
        return number;
    }
    bool check(int number) {
        return number >= 0 && number < (int)used.size() && !used[number];
    }
    void release(int number) {
        if (number < 0 || number >= (int)used.size() || !used[number]) return;
        used[number] = false;
        freeNumbers.push(number);
    }
};
